REPLACE INTO `item_combos` (`row_id`,`payload_json`) VALUES (4959,'{"Combos":[{"Combo":["Time_Gap_SHC_Dagger1","Time_Gap_SHC_Dagger2"]}],"Script":"if (getequipid(EQI_HAND_L) == 510166) {\\n   .@sum = getequiprefinerycnt(EQI_HAND_R)\\u002Bgetequiprefinerycnt(EQI_HAND_L);\\n   bonus bAtkRate,.@sum;\\n   bonus bBaseAtk,25*.@sum;\\n   bonus2 bSkillAtk,\\u0022SHC_CROSS_SLASH\\u0022,5*(.@sum/4);\\n   if (.@sum\\u003E=14) {\\n      bonus bCritAtkRate,20;\\n      if (.@sum\\u003E=17) {\\n         bonus bCRate,5;\\n         bonus bCritical,15;\\n         if (.@sum\\u003E=21) {\\n            bonus2 bSkillAtk,\\u0022SHC_CROSS_SLASH\\u0022,15;\\n         }\\n      }\\n   }\\n}\\n"}');
